package store

import (
	"database/sql"
	"fmt"
	"strings"

	"shingo/protocol/migrate"
	"shingoedge/store/schema"
)

// RetiredChain is the last version of the chain the baseline retires: a
// database born on the baseline records 1..RetiredChain, and the baseline is
// generated by booting RetiredChainRelease, the release that carries that
// whole chain (internal/schemadump.GenerateBaseline). An Edge starts on no
// database that lacks one of those versions; RetiredChainRelease is the
// release that applies them. The release tool reads RetiredChain as versions
// this file declares (shared/scripts/release MigrationVersions).
const (
	RetiredChain        = 59
	RetiredChainRelease = "v0.19.0"
)

// edgeMigrations is every migration above RetiredChain, ascending
// (TestEdgeMigrations_Shape). It is the only place an Edge schema change goes.
// A new entry's Version is the one before it plus one, and the baseline is
// regenerated after it (make schema-baseline, then make schema-snapshot). A
// migration that adds a style_node_claims column adds the same column to
// style_node_claims_quarantine (TestClaimQuarantine_MirrorsEveryClaimColumn).
//
// There is no down step: protocol/migrate has none, and a migration here
// leaves the previous release able to run on what it leaves.
func edgeMigrations() []migrate.Migration {
	return []migrate.Migration{
		{Version: 60, Name: "converge_and_drop_dead_columns", Fn: v60Up, Verify: v60Verify},
	}
}

// latestVersion is the highest version this build records: the last entry of
// edgeMigrations, or RetiredChain while the list is empty.
func latestVersion() int {
	return max(RetiredChain, migrate.LatestVersion(edgeMigrations()))
}

// migrate brings a file that checkFile accepted to this build's schema.
//
//   - A new file (no tables) is born on the baseline (store/schema/baseline.sql):
//     every table and index, and schema_migrations 1..the baseline's head, in
//     one transaction.
//   - An existing one holds 1..RetiredChain whole (checkFile refused it
//     otherwise) and runs the migrations above it through the shared runner,
//     protocol/migrate: each with its schema_migrations row in one
//     transaction, and re-run when its Verify says its state is gone.
//
// Nothing else runs at a start that changes the schema: no DDL replay and no
// repair pass.
func (db *DB) migrate(fresh bool) error {
	if fresh {
		if err := db.Transaction(applyBaseline); err != nil {
			return err
		}
	}
	return db.runVersioned(edgeMigrations())
}

// applyBaseline runs the baseline as one Exec in the caller's transaction, so
// a birth that fails part-way leaves no table behind.
func applyBaseline(tx *sql.Tx) error {
	if _, err := tx.Exec(schema.Baseline); err != nil {
		return fmt.Errorf("apply the baseline to an empty database: %w", err)
	}
	return nil
}

// runVersioned is the seam versioned_migration_test.go drives directly; the
// production call is migrate's.
func (db *DB) runVersioned(ms []migrate.Migration) error {
	return migrate.Run(db.DB, migrate.SQLite, 0, ms)
}

// Migrate brings the file at path to this build's versions and does nothing
// else a start does: no schema verification, no startup step. It is the
// baseline generator's door (internal/schemadump.GenerateBaseline), which
// runs before the baseline it would be verified against exists.
func Migrate(path string) error {
	cur, err := checkFile(path, connectSQLite)
	if err != nil {
		return err
	}
	db, err := connectStore(path, connectSQLite)
	if err != nil {
		return err
	}
	defer db.Close()
	return db.migrate(cur == 0)
}

// AppliedSchemaVersion is the version the boot migration left this database
// at — what the register payload reports to Core's /edges page and its landing
// gate. The readers are the heartbeater's SchemaVersionFn (wired in main.go)
// and the engine's SchemaVersion, which the debug page's register sends; it
// exists as a DB method so the accessor travels with the runner it reads for.
// -1 on a read failure, which the wire carries as "knows but cannot read"
// rather than as the pre-runner 0.
func (db *DB) AppliedSchemaVersion() int {
	v, err := migrate.Latest(db.DB, migrate.SQLite)
	if err != nil {
		return -1
	}
	return v
}

// formatVersions writes ascending versions as ranges: v30, v41–v59.
func formatVersions(vs []int) string {
	var parts []string
	for i := 0; i < len(vs); {
		j := i
		for j+1 < len(vs) && vs[j+1] == vs[j]+1 {
			j++
		}
		if j == i {
			parts = append(parts, fmt.Sprintf("v%d", vs[i]))
		} else {
			parts = append(parts, fmt.Sprintf("v%d–v%d", vs[i], vs[j]))
		}
		i = j + 1
	}
	return strings.Join(parts, ", ")
}
